#!/usr/bin/env python3
# The file is mixed encoding. Let's read line by line and fix problematic ones.
with open('taipei-trip-zh.typ', 'rb') as f:
    lines = f.readlines()

# The issue: some lines have ??? instead of 住宿
# These are likely Big5-encoded bytes that can't be decoded as UTF-8
# Solution: read the file with big5, find the lines, replace them

# First, let's identify the exact byte pattern in the bad lines
for i, line in enumerate(lines):
    if i in [813, 925, 1037, 1147, 1258]:
        print(f"Bad line {i+1}: {line}")
        # Try decoding as different encodings
        for enc in ['big5', 'cp950', 'gb2312', 'gbk']:
            try:
                decoded = line.decode(enc)
                print(f"  Decodes as {enc}: {decoded.strip()[:60]}")
            except Exception as e:
                print(f"  Fails {enc}: {e}")

